package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ScrapeIntervalVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property scrape interval of observed source ")
  void test_scrape_interval_v_o_builder() {
    Assertions.assertFalse(ScrapeIntervalVO.nullValue().getScrapeInterval().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ScrapeIntervalVO.tryFrom(null).getScrapeInterval().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, ScrapeIntervalVO.from(1).getScrapeInterval().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ScrapeIntervalVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ScrapeIntervalVO.from(1).toString());
  }
}
